 private function fixture(?bool $active):array{$w=(new ReflectionClass(CircleNativeShareWrapperService::class))->newInstanceWithoutConstructor();foreach(['request'=>new ShareWrapperRequest(),'assertFresh'=>static fn()=>null,'actorUid'=>'actor','currentRecipient'=>'member','transferCapability'=>$active===null?null:new ShareWriteBoundary($active),'childGrant'=>null]as$k=>$v)(new ReflectionProperty($w,$k))->setValue($w,$v);$share=$this->createMock(\OCP\Share\IShare::class);foreach(['getId'=>'31','getShareType'=>7,'getSharedWith'=>'circle','getNodeId'=>11,'getPermissions'=>1]as$m=>$v)$share->method($m)->willReturn($v);return[$w,$share];}
