 public function testNewGrantImmediatelyBeforeHydrationIsDenied():void{[$w,$share]=$this->fixture(true);ShareWrapperRequest::$before=static function()use($w):void{(new ReflectionProperty($w,'childGrant'))->setValue($w,['changed'=>true]);};$this->expectException(RuntimeException::class);$this->expectExceptionMessage('Circle child creation cannot enter the pure lookup');try{$w->getChild($share,new \OCA\Circles\Model\FederatedUser());}finally{self::assertSame(0,ShareWrapperRequest::$queries);self::assertFalse(ShareWriteBoundary::$active);}}
